// Translation the theme
function badoblog_fun_language_theme() {
    load_theme_textdomain( 'bado-blog', false, get_template_directory() . '/languages' );
    // Language TABs Freemius
    fs_override_i18n( array(
        'contact-us'  => esc_html__( 'Contact', 'bado-blog' ),
        'account'     => esc_html__( 'Account', 'bado-blog' ),
        'pricing'     => esc_html__( 'Pricing', 'bado-blog' ),
        'upgrade'     => esc_html__( 'Upgrade', 'bado-blog' ),
        'add-ons'     => esc_html__( 'Add-Ons', 'bado-blog' ),
        'affiliation' => esc_html__( 'Affiliate program', 'bado-blog' ),
    ), 'bado-blog' );
    // Theme description (for translations - style.css)
    esc_html__( 'Bado Blog is a cool, modern multipurpose WordPress theme with many free settings to create a responsive, fast, SEO optimized website that is easy to modify with a visual customizer. Bado Blog is well suited for magazines, personal blogs, article sites, news, and media. Translated into 20+ languages. Easy to use without coding knowledge. Good flexibility and functionality - multiple site width options (with full-width option), change sidebar orientation (left, right, or no sidebar), category grids with vertical and horizontal posts of various sizes, flexible header with logo, social link builder, ticker, 4 menu locations, main menu (mega menu), breadcrumbs, three pagination options, author block, related posts block, and styled widgets. Powerful Typography – change font size and line height, choose font designs, color typography for posts and pages. Clean code, no frameworks, minimum scripts. Good adaptability for any mobile devices. SEO-optimized with correct headings and markup. Adaptation for WooCommerce, Elementor, bbPress, Events Calendar, Jetpack, WPML, Contact Form 7, and Newsletter. Demo – web-zone.org/bado-blog', 'bado-blog' );
}

add_action( 'init', 'badoblog_fun_language_theme' );
